    54→          const action = {
    55→            type: userAction.name,
    56→            actionType: userAction.name,
    57→            surfaceId: userAction.surfaceId,
    58→            sourceComponentId: userAction.sourceComponentId,
    59→            timestamp: userAction.timestamp,
