    72→  ngOnDestroy(): void {
    73→    this.eventsSubscription.unsubscribe();
    74→  }
    75→
    76→  // Core signals - currentSurfaceId tracks which surface to display
    77→  readonly currentSurfaceId = signal<string | null>(null);
    78→  readonly catalogValidationError = signal<string | null>(null);
    79→
    80→  // Ordered list of surfaceIds as they arrive (for rendering all visualizations)
    81→  readonly surfaceHistory = signal<string[]>([]);
    82→
    83→  // Computed signal that gets the actual surface from the processor
    84→  readonly currentSurface = computed(() => {
    85→    const surfaceId = this.currentSurfaceId();
    86→    if (!surfaceId) return null;
    87→
    88→    const surfaces = this.messageProcessor.getSurfaces();
    89→    return surfaces.get(surfaceId) || null;
    90→  });
    91→
    92→  // All surfaces in order, for the canvas feed
    93→  readonly allSurfaces = computed(() => {
    94→    const ids = this.surfaceHistory();
    95→    const surfaceMap = this.messageProcessor.getSurfaces();
    96→    return ids
    97→      .map((id) => {
    98→        const surface = surfaceMap.get(id);
    99→        if (!surface) return null;
   100→        const tree: any = surface.componentTree;
   101→        const title = tree?.properties?.title || tree?.type || 'Visualization';
   102→        return { id, surface, title };
   103→      })
   104→      .filter((entry): entry is NonNullable<typeof entry> => entry !== null);
   105→  });
   106→
   107→  /**
   108→   * Handle A2UI messages from the backend.
   109→   *
   110→   * Backend sends its own format:
   111→   *   { beginRendering: {root, surfaceId} }
   112→   *   { updateComponents: { components: [ {id, component: "Graph", ...props} ] } }
   113→   *
   114→   * We transform this into proper A2UI ServerToClientMessage format:
   115→   *   { beginRendering: {root, surfaceId} }
   116→   *   { surfaceUpdate:  { surfaceId, components: [ {id, component: {Graph: {...props}}} ] } }
   117→   *
   118→   * Then feed it to MessageProcessor.processMessages() which builds the
   119→   * resolved component tree automatically.
   120→   */
   121→  handleA2UIMessages(surfaceId: string, messages: any[]): void {
   122→    try {
   123→      // 1. Extract updateComponents (required)
   124→      const updateMsg = messages.find((m: any) => 'updateComponents' in m);
   125→      if (!updateMsg?.updateComponents?.components?.length) {
   126→        console.error('No updateComponents message found');
   127→        return;
   128→      }
   129→
   130→      // Flatten backend components into A2UI ComponentInstance format
   131→      const a2uiComponents: any[] = [];
   132→      for (const backendComp of updateMsg.updateComponents.components) {
   133→        this.flattenBackendComponent(backendComp, a2uiComponents);
   134→      }
   135→
   136→      // Determine root component ID: prefer beginRendering.root,
   137→      // fall back to first backend component's id
   138→      const beginMsg = messages.find((m: any) => 'beginRendering' in m);
   139→      const rootId =
   140→        beginMsg?.beginRendering?.root ??
   141→        beginMsg?.beginRendering?.rootComponentId ??
   142→        updateMsg.updateComponents.components[0].id;
   143→
   144→      // 2. Build proper ServerToClientMessage array
   145→      const a2uiMessages: any[] = [
   146→        {
   147→          beginRendering: {
   148→            surfaceId,
   149→            root: rootId,
   150→          },
   151→        },
   152→        {
   153→          surfaceUpdate: {
   154→            surfaceId,
   155→            components: a2uiComponents,
   156→          },
   157→        },
   158→      ];
   159→
   160→      // 3. Feed properly formatted messages to the MessageProcessor
   161→      this.messageProcessor.processMessages(a2uiMessages);
   162→
   163→      // 4. Update the current surface ID (triggers computed signal)
   164→      this.currentSurfaceId.set(surfaceId);
   165→      this.surfaceHistory.update((ids) => [...ids, surfaceId]);
   166→      this.catalogValidationError.set(null);
   167→    } catch (error: any) {
   168→      console.error('Failed to process A2UI messages:', error);
   169→      this.catalogValidationError.set(error.message || 'Failed to process visualization');
   170→    }
   171→  }
   172→
   173→  /**
   174→   * Transform a backend component into A2UI ComponentInstance format and
   175→   * recursively flatten any nested children into separate ComponentInstance entries.
   176→   *
   177→   * Backend format (flat):
   178→   *   { id: "root", component: "CompositeDashboard", title: "...", children: { kpis: [...], charts: [...] } }
   179→   *
   180→   * A2UI format (nested key = type):
   181→   *   { id: "root", component: { CompositeDashboard: { title: "...", children: { explicitList: [...] } } } }
   182→   *
   183→   * Children are extracted, given their own ComponentInstance entries, and
   184→   * referenced via explicitList IDs.
   185→   */
   186→  private flattenBackendComponent(backendComp: any, result: any[]): void {
   187→    const { id, component: componentType, children, ...props } = backendComp;
   188→
   189→    // Build the A2UI ComponentInstance
   190→    const componentProps: any = { ...props };
   191→
   192→    if (children && typeof children === 'object') {
   193→      if (children.explicitList) {
   194→        // Already in A2UI ComponentArrayReference format — pass through directly
   195→        componentProps.children = children;
   196→      } else {
   197→        // Nested component objects: either an array or categorized object
   198→        const childComponents: any[] = [];
   199→        const childIds: string[] = [];
   200→
   201→        if (Array.isArray(children)) {
   202→          childComponents.push(...children);
   203→        } else {
   204→          // Object with category keys: { kpis: [...], charts: [...] }
   205→          for (const category of Object.values(children)) {
   206→            if (Array.isArray(category)) {
   207→              childComponents.push(...category);
   208→            }
   209→          }
   210→        }
   211→
   212→        // Recursively flatten each child component
   213→        for (const child of childComponents) {
   214→          if (child && child.id && child.component) {
   215→            childIds.push(child.id);
   216→            this.flattenBackendComponent(child, result);
   217→          }
   218→        }
   219→
   220→        if (childIds.length > 0) {
   221→          componentProps.children = { explicitList: childIds };
   222→        }
   223→      }
   224→    }
   225→
   226→    result.push({
   227→      id,
   228→      component: {
   229→        [componentType]: componentProps,
   230→      },
   231→    });
   232→  }
   233→
   234→  /**
   235→   * Clear all surfaces
   236→   */
   237→  clearSurface(): void {
   238→    this.messageProcessor.clearSurfaces();
   239→    this.currentSurfaceId.set(null);
   240→    this.surfaceHistory.set([]);
   241→    this.catalogValidationError.set(null);
   242→  }
   243→
   244→  /**
   245→   * Handle A2UI action events (drill-downs, detail requests)
   246→   * Generates natural language follow-up messages and triggers agent
   247→   */
   248→  async handleA2UIAction(action: any): Promise<void> {
   249→    if (!FEATURE_FLAGS.DRILL_DOWN_ENABLED) return;
   250→
   251→    let message = '';
   252→    let filterContext: any = {};
   253→
   254→    // Generate message based on action type
   255→    switch (action.actionType || action.type) {
   256→      case 'drill_down':
   257→        if (action.label && action.value !== undefined) {
   258→          message = `Show details for ${action.label}`;
   259→          if (action.datasetLabel) {
   260→            message += ` from ${action.datasetLabel}`;
   261→          }
   262→          filterContext = {
   263→            drillDownLabel: action.label,
   264→            drillDownValue: action.value,
   265→            drillDownDataset: action.datasetLabel,
   266→          };
   267→        } else if (action.row) {
   268→          // Table row drill-down
   269→          const firstValue = Object.values(action.row)[0];
   270→          message = `Show details for ${firstValue}`;
   271→          filterContext = {
   272→            drillDownRow: action.row,
   273→          };
   274→        }
   275→        break;
   276→
   277→      case 'detail_request':
   278→        message = `Tell me more about ${action.label || 'this item'}`;
   279→        filterContext = {
   280→          detailRequest: action.label,
   281→        };
   282→        break;
   283→
   284→      default:
   285→        console.warn('Unknown A2UI action type:', action.actionType || action.type);
   286→        return;
   287→    }
   288→
   289→    if (!message) return;
   290→
   291→    // Lazy inject services to avoid circular dependencies
   292→    const chatState = this.injector.get(ChatStateService);
   293→    const sharedState = this.injector.get(SharedStateService);
   294→    const agUiService = this.injector.get(AgUiService);
   295→
   296→    // Update shared state with drill-down context
   297→    if (Object.keys(filterContext).length > 0) {
   298→      sharedState.updateContext({
   299→        activeFilters: filterContext,
   300→      });
   301→    }
   302→
   303→    // Add user message and trigger agent
   304→    chatState.addUserMessage(message);
   305→
   306→    try {
   307→      await agUiService.runAgent();
   308→    } catch (error) {
   309→      const errorMsg = error instanceof Error ? error.message : 'Failed to process drill-down';
   310→      console.error('Failed to run agent after drill-down:', error);
   311→      chatState.setError(errorMsg);
   312→    }
   313→  }
   314→}
