     9→/**
    10→ * A2UIEventService
    11→ *
    12→ * Bridges AG-UI custom events to A2UI Angular renderer with fallback strategy.
    13→ * Validates A2UI payloads against the registered catalog.
    14→ */
    15→@Injectable({
    16→  providedIn: 'root',
    17→})
    18→export class A2UIEventService implements OnDestroy {
    19→  private messageProcessor = inject(MessageProcessor);
    20→  private injector = inject(Injector);
