    22→
    23→  constructor() {
    24→    // Subscribe to A2UI events from the MessageProcessor
    25→    this.eventsSubscription = this.messageProcessor.events.subscribe((event) => {
    26→      // Always complete the event to prevent MessageProcessor from hanging
    27→      try {
    28→        if (!FEATURE_FLAGS.DRILL_DOWN_ENABLED) {
    29→          return;
    30→        }
    31→        if (event.message && event.message.userAction) {
    32→          const userAction = event.message.userAction;
    33→
    34→          // Build action object from the userAction
    35→          // The context can be either:
    36→          // 1. An array of {key, value} pairs (A2UI spec format)
    37→          // 2. A flat object (A2UI library auto-transforms arrays to objects)
    38→          const contextProps: any = {};
    39→
    40→          if (Array.isArray(userAction.context)) {
    41→            for (const item of userAction.context) {
    42→              if (item.key && item.value) {
    43→                const actualValue = item.value.literalString
    44→                  ?? item.value.literalNumber
    45→                  ?? item.value.literalBoolean
    46→                  ?? item.value.path;
    47→                contextProps[item.key] = actualValue;
    48→              }
    49→            }
    50→          } else if (typeof userAction.context === 'object' && userAction.context !== null) {
    51→            Object.assign(contextProps, userAction.context);
    52→          }
    53→
    54→          const action = {
    55→            type: userAction.name,
    56→            actionType: userAction.name,
    57→            surfaceId: userAction.surfaceId,
    58→            sourceComponentId: userAction.sourceComponentId,
    59→            timestamp: userAction.timestamp,
    60→            ...contextProps,
    61→          };
    62→
    63→          this.handleA2UIAction(action);
    64→        }
    65→      } finally {
    66→        event.completion.next([]);
    67→        event.completion.complete();
    68→      }
    69→    });
    70→  }
    71→
    72→  ngOnDestroy(): void {
    73→    this.eventsSubscription.unsubscribe();
    74→  }
    75→
    76→  // Core signals - currentSurfaceId tracks which surface to display
    77→  readonly currentSurfaceId = signal<string | null>(null);
