    36→      </button>
    37→      <button
    38→        role="tab"
    39→        [attr.aria-selected]="activeTab() === 'canvas'"
    40→        aria-controls="panel-canvas"
    41→        (click)="activeTab.set('canvas')"
    42→        class="flex-1 px-6 py-3 text-sm font-medium transition-colors relative"
    43→        [class.text-blue-600]="activeTab() === 'canvas'"
    44→        [class.text-gray-500]="activeTab() !== 'canvas'">
    45→        Canvas
    46→        @if (activeTab() === 'canvas') {
    47→          <div class="absolute bottom-0 left-0 right-0 h-0.5 bg-blue-600"></div>
    48→        }
    49→      </button>
    50→    </div>
    51→
    52→    <!-- Main content area (single ng-content per slot) -->
    53→    <div #desktopContainer class="flex-1 flex overflow-hidden">
    54→      <!-- Chat panel -->
    55→      <div
    56→        id="panel-chat"
    57→        role="tabpanel"
