   118→export class SplitViewComponent implements OnInit, OnDestroy, AfterViewInit {
   119→  @ViewChild('desktopContainer') desktopContainer?: ElementRef<HTMLElement>;
   120→
   121→  // Signals for layout state
   122→  readonly chatWidth = signal<number>(40); // percentage
   123→  readonly activeTab = signal<'chat' | 'canvas'>('chat');
   124→  readonly isDragging = signal(false);
   125→  readonly isCanvasFullscreen = signal(false);
   126→
   127→  // Constraints
   128→  private readonly MIN_CHAT_WIDTH_PCT = 20;
   129→  private readonly MAX_CHAT_WIDTH_PCT = 70;
   130→  private readonly STORAGE_KEY = 'split-ratio';
   131→
   132→  // Native drag state
   133→  private startX = 0;
   134→  private startWidth = 0;
   135→  private containerWidth = 0;
   136→
   137→  // Bound handlers for cleanup
   138→  private boundPointerMove = this.onPointerMove.bind(this);
   139→  private boundPointerUp = this.onPointerUp.bind(this);
   140→
   141→  ngOnInit(): void {
   142→    this.loadSplitRatio();
   143→  }
   144→
   145→  ngAfterViewInit(): void {
   146→    this.updateContainerWidth();
   147→    window.addEventListener('resize', this.onResize);
   148→  }
   149→
   150→  ngOnDestroy(): void {
   151→    window.removeEventListener('resize', this.onResize);
   152→    document.removeEventListener('pointermove', this.boundPointerMove);
   153→    document.removeEventListener('pointerup', this.boundPointerUp);
   154→  }
   155→
   156→  private onResize = (): void => {
   157→    this.updateContainerWidth();
   158→  };
   159→
   160→  /**
   161→   * Start divider drag using native pointer events
   162→   */
   163→  onDividerPointerDown(event: PointerEvent): void {
   164→    event.preventDefault();
   165→    this.updateContainerWidth();
   166→
   167→    this.isDragging.set(true);
   168→    this.startX = event.clientX;
   169→    this.startWidth = this.chatWidth();
   170→
   171→    // Capture pointer for smooth tracking even outside the element
   172→    (event.target as HTMLElement).setPointerCapture(event.pointerId);
   173→
   174→    document.addEventListener('pointermove', this.boundPointerMove);
   175→    document.addEventListener('pointerup', this.boundPointerUp);
   176→
   177→    // Prevent text selection during drag
   178→    document.body.style.userSelect = 'none';
   179→    document.body.style.cursor = 'col-resize';
   180→  }
   181→
   182→  private onPointerMove(event: PointerEvent): void {
   183→    if (!this.isDragging()) return;
   184→
   185→    const deltaX = event.clientX - this.startX;
   186→    const deltaPct = (deltaX / this.containerWidth) * 100;
   187→    let newWidth = this.startWidth + deltaPct;
   188→
   189→    // Clamp to constraints
   190→    newWidth = Math.max(this.MIN_CHAT_WIDTH_PCT, Math.min(this.MAX_CHAT_WIDTH_PCT, newWidth));
   191→
   192→    this.chatWidth.set(newWidth);
   193→  }
   194→
   195→  private onPointerUp(): void {
   196→    this.isDragging.set(false);
   197→
   198→    document.removeEventListener('pointermove', this.boundPointerMove);
   199→    document.removeEventListener('pointerup', this.boundPointerUp);
   200→
   201→    // Restore text selection and cursor
   202→    document.body.style.userSelect = '';
   203→    document.body.style.cursor = '';
   204→
   205→    this.saveSplitRatio();
   206→  }
   207→
   208→  /**
   209→   * Save split ratio to localStorage
   210→   */
   211→  private saveSplitRatio(): void {
   212→    try {
   213→      localStorage.setItem(this.STORAGE_KEY, this.chatWidth().toString());
   214→    } catch (e) {
   215→      console.warn('Failed to save split ratio to localStorage', e);
   216→    }
   217→  }
   218→
   219→  /**
   220→   * Load split ratio from localStorage
   221→   */
   222→  private loadSplitRatio(): void {
   223→    try {
   224→      const saved = localStorage.getItem(this.STORAGE_KEY);
   225→      if (saved) {
   226→        const ratio = parseFloat(saved);
   227→        if (!isNaN(ratio) && ratio >= this.MIN_CHAT_WIDTH_PCT && ratio <= this.MAX_CHAT_WIDTH_PCT) {
   228→          this.chatWidth.set(ratio);
   229→        }
   230→      }
   231→    } catch (e) {
   232→      console.warn('Failed to load split ratio from localStorage', e);
   233→    }
   234→  }
   235→
   236→  /**
   237→   * Update tracked container width
   238→   */
   239→  private updateContainerWidth(): void {
   240→    if (this.desktopContainer?.nativeElement) {
   241→      this.containerWidth = this.desktopContainer.nativeElement.offsetWidth;
   242→    } else {
   243→      this.containerWidth = window.innerWidth;
   244→    }
   245→  }
   246→
   247→  /**
   248→   * Set mobile/tablet view (called by parent via ViewChild)
   249→   * Uses activeTab signal which drives CSS visibility on smaller screens.
   250→   */
   251→  setMobileView(view: 'chat' | 'canvas'): void {
   252→    this.activeTab.set(view);
   253→  }
   254→
   255→  toggleCanvasFullscreen(): void {
   256→    this.isCanvasFullscreen.update((v) => !v);
   257→  }
   258→}
   259→

