     8→/**
     9→ * AgUiService
    10→ *
    11→ * Wraps @ag-ui/client HttpAgent and bridges AG-UI events to Angular signals.
    12→ * Orchestrates all agent communication via SSE streaming.
    13→ *
    14→ * CRITICAL SERVICE: All agent interactions flow through here.
    15→ */
    16→@Injectable({
    17→  providedIn: 'root',
    18→})
    19→export class AgUiService {
    20→  private chatState = inject(ChatStateService);
    21→  private sharedState = inject(SharedStateService);
    22→  private a2uiEventService = inject(A2UIEventService);
    23→
    24→  private agent: HttpAgent;
    25→  private streamTimeout: ReturnType<typeof setTimeout> | null = null;
    26→  private readonly STREAM_TIMEOUT_MS = 180_000; // 3 minutes
    27→
    28→  constructor() {
    29→    // Initialize the HttpAgent — threadId is auto-generated by the library (uuid v4)
    30→    this.agent = new HttpAgent({
    31→      url: `${environment.apiUrl}${environment.agentEndpoint}`,
    32→    });
    33→  }
    34→
    35→  /**
    36→   * Run the agent with current messages and shared state
    37→   * Uses HttpAgent from @ag-ui/client to handle request formatting
    38→   */
    39→  async runAgent(): Promise<void> {
    40→    try {
    41→      // Recreate agent with updated messages/state; preserve the
    42→      // library-generated threadId (uuid v4) from the original instance.
    43→      const threadId = this.agent.threadId;
    44→      this.agent = new HttpAgent({
    45→        url: `${environment.apiUrl}${environment.agentEndpoint}`,
    46→        threadId,
    47→        initialMessages: this.chatState
    48→          .messages()
    49→          .filter((msg) => msg.role === 'user')
    50→          .slice(-environment.maxMessageHistory)
    51→          .map((msg, index) => ({
    52→            id: msg.id || `msg-${index}`,
    53→            role: 'user' as const,
    54→            content: [{ type: 'text' as const, text: msg.content }],
    55→          })),
    56→        initialState: this.sharedState.agentContext(),
    57→      });
    58→
    59→      // Start streaming
    60→      this.chatState.isStreaming.set(true);
    61→
    62→      // Set stream timeout to prevent infinite hangs
    63→      this.streamTimeout = setTimeout(() => {
    64→        console.warn(`Agent stream timeout after ${this.STREAM_TIMEOUT_MS / 1000}s, aborting`);
    65→        this.cancel();
    66→        this.chatState.setError('Agent response timed out — please try again');
    67→      }, this.STREAM_TIMEOUT_MS);
    68→
    69→      // Run agent with typed subscriber callbacks
    70→      await this.agent.runAgent(
    71→        {
    72→          tools: [],
    73→          context: [],
    74→          forwardedProps: {},
    75→        },
    76→        this.buildSubscriber(),
    77→      );
    78→    } catch (error: any) {
    79→      this.clearStreamTimeout();
    80→      // Suppress noisy AGUIError when library sends RUN_FINISHED after RUN_ERROR
    81→      const msg = error?.message || '';
    82→      if (msg.includes('The run has already errored')) {
    83→        return;
    84→      }
    85→      console.error('Agent error:', error);
    86→      this.chatState.setError(msg || 'Failed to connect to agent');
    87→      this.chatState.isStreaming.set(false);
    88→    }
    89→  }
    90→
    91→  /**
    92→   * Clear the stream timeout if active
    93→   */
    94→  private clearStreamTimeout(): void {
    95→    if (this.streamTimeout) {
    96→      clearTimeout(this.streamTimeout);
    97→      this.streamTimeout = null;
    98→    }
    99→  }
   100→
   101→  /**
   102→   * Cancel the current agent stream
   103→   */
   104→  cancel(): void {
   105→    this.clearStreamTimeout();
   106→    this.agent.abortRun();
