   110→
   111→  /**
   112→   * Build a typed AgentSubscriber — replaces the manual switch(event.type).
   113→   * Each callback receives typed event data and accumulated buffers from the library.
   114→   */
   115→  private buildSubscriber(): AgentSubscriber {
   116→    return {
   117→      // ── Logging (fires for every event) ────────────────────────
   118→      onEvent: ({ event }) => {
   119→        console.log('AG-UI Event:', event.type, event);
   120→      },
   121→
   122→      // ── Lifecycle ─────────────────────────────────────────────
   123→      onRunStartedEvent: () => {
   124→        this.chatState.isStreaming.set(true);
   125→      },
   126→
   127→      onRunFinishedEvent: () => {
   128→        this.chatState.isStreaming.set(false);
   129→      },
   130→
   131→      onRunErrorEvent: ({ event }) => {
   132→        // Suppress user-initiated abort — not an actual error
   133→        if (('code' in event && (event as any).code === 'abort') ||
   134→            ('message' in event && String((event as any).message).includes('aborted'))) {
   135→          return;
   136→        }
   137→        if (this.chatState.currentStreamingMessage()) {
   138→          this.chatState.finalizeStreamingMessage();
   139→        }
   140→        const errorMessage = (event as any).error ?? 'Agent error';
   141→        this.chatState.setError(typeof errorMessage === 'string' ? errorMessage : 'Agent error');
   142→        this.chatState.isStreaming.set(false);
   143→      },
   144→
   145→      onRunFailed: ({ error }) => {
   146→        this.clearStreamTimeout();
   147→        const msg = error?.message || '';
   148→        if (msg.includes('The run has already errored') || msg.includes('aborted')) {
   149→          return;
   150→        }
   151→        console.error('Agent error:', error);
   152→        this.chatState.setError(msg || 'Failed to connect to agent');
   153→        this.chatState.isStreaming.set(false);
   154→      },
   155→
   156→      onRunFinalized: () => {
   157→        this.clearStreamTimeout();
   158→        this.chatState.finalizeStreamingMessage();
   159→        this.chatState.isStreaming.set(false);
   160→      },
   161→
   162→      // ── Text message streaming ────────────────────────────────
   163→      onTextMessageStartEvent: () => {
