   189→      },
   190→
   191→      onToolCallArgsEvent: ({ toolCallName, partialToolCallArgs }) => {
   192→        this.chatState.addToolCall({
   193→          toolName: toolCallName,
   194→          status: 'running',
   195→          arguments: partialToolCallArgs,
   196→        });
   197→      },
   198→
   199→      onToolCallEndEvent: ({ toolCallName }) => {
   200→        this.chatState.addToolCall({
   201→          toolName: toolCallName,
   202→          status: 'complete',
   203→        });
   204→      },
