     1→import { Injectable, inject } from '@angular/core';
     2→import { HttpAgent, AgentSubscriber } from '@ag-ui/client';
     3→import { ChatStateService } from './chat-state.service';
     4→import { SharedStateService } from './shared-state.service';
     5→import { A2UIEventService } from './a2ui-event.service';
     6→import { environment } from '../../../environments/environment';
     7→
     8→/**
     9→ * AgUiService
    10→ *
    11→ * Wraps @ag-ui/client HttpAgent and bridges AG-UI events to Angular signals.
    12→ * Orchestrates all agent communication via SSE streaming.
    13→ *
    14→ * CRITICAL SERVICE: All agent interactions flow through here.
    15→ */
    16→@Injectable({
    17→  providedIn: 'root',
    18→})
    19→export class AgUiService {
    20→  private chatState = inject(ChatStateService);
    21→  private sharedState = inject(SharedStateService);
    22→  private a2uiEventService = inject(A2UIEventService);
    23→
    24→  private agent: HttpAgent;
    25→  private streamTimeout: ReturnType<typeof setTimeout> | null = null;
    26→  private readonly STREAM_TIMEOUT_MS = 180_000; // 3 minutes
    27→
    28→  constructor() {
    29→    // Initialize the HttpAgent — threadId is auto-generated by the library (uuid v4)
    30→    this.agent = new HttpAgent({
    31→      url: `${environment.apiUrl}${environment.agentEndpoint}`,
    32→      headers: { 'X-User-Id': environment.userId },
    33→    });
    34→  }
    35→
    36→  /** Current thread ID from the underlying HttpAgent */
    37→  get threadId(): string {
    38→    return this.agent.threadId;
    39→  }
    40→
    41→  /**
    42→   * Run the agent with current messages and shared state
    43→   * Uses HttpAgent from @ag-ui/client to handle request formatting
    44→   */
    45→  async runAgent(): Promise<void> {
    46→    try {
    47→      // Recreate agent with preserved threadId. Backend uses persisted history,
    48→      // so we only send the latest user message (not full conversation).
    49→      const threadId = this.agent.threadId;
    50→      const latestUserMsg = this.chatState
    51→        .messages()
    52→        .filter((msg) => msg.role === 'user')
    53→        .slice(-1)
    54→        .map((msg) => ({
    55→          id: msg.id,
    56→          role: 'user' as const,
    57→          content: [{ type: 'text' as const, text: msg.content }],
    58→        }));
    59→
    60→      this.agent = new HttpAgent({
    61→        url: `${environment.apiUrl}${environment.agentEndpoint}`,
    62→        threadId,
    63→        headers: { 'X-User-Id': environment.userId },
    64→        initialMessages: latestUserMsg,
    65→        initialState: this.sharedState.agentContext(),
    66→      });
    67→
    68→      // Start streaming
    69→      this.chatState.isStreaming.set(true);
    70→
    71→      // Set stream timeout to prevent infinite hangs
    72→      this.streamTimeout = setTimeout(() => {
    73→        console.warn(`Agent stream timeout after ${this.STREAM_TIMEOUT_MS / 1000}s, aborting`);
    74→        this.cancel();
    75→        this.chatState.setError('Agent response timed out — please try again');
    76→      }, this.STREAM_TIMEOUT_MS);
    77→
    78→      // Run agent with typed subscriber callbacks
    79→      await this.agent.runAgent(
    80→        {
    81→          tools: [],
    82→          context: [],
    83→          forwardedProps: {},
    84→        },
    85→        this.buildSubscriber(),
    86→      );
    87→    } catch (error: any) {
    88→      this.clearStreamTimeout();
    89→      // Suppress noisy AGUIError when library sends RUN_FINISHED after RUN_ERROR
    90→      const msg = error?.message || '';
    91→      if (msg.includes('The run has already errored')) {
    92→        return;
    93→      }
    94→      console.error('Agent error:', error);
    95→      this.chatState.setError(msg || 'Failed to connect to agent');
    96→      this.chatState.isStreaming.set(false);
    97→    }
    98→  }
    99→
   100→  /**
   101→   * Clear the stream timeout if active
   102→   */
   103→  private clearStreamTimeout(): void {
   104→    if (this.streamTimeout) {
   105→      clearTimeout(this.streamTimeout);
   106→      this.streamTimeout = null;
   107→    }
   108→  }
   109→
   110→  /**
   111→   * Cancel the current agent stream
   112→   */
   113→  cancel(): void {
   114→    this.clearStreamTimeout();
   115→    this.agent.abortRun();
   116→    this.chatState.finalizeStreamingMessage();
   117→    this.chatState.isStreaming.set(false);
   118→  }
   119→
   120→  /**
   121→   * Build a typed AgentSubscriber — replaces the manual switch(event.type).
   122→   * Each callback receives typed event data and accumulated buffers from the library.
   123→   */
   124→  private buildSubscriber(): AgentSubscriber {
   125→    return {
   126→      // ── Logging (fires for every event) ────────────────────────
   127→      onEvent: ({ event }) => {
   128→        console.log('AG-UI Event:', event.type, event);
   129→      },
