// ── Mapping functions ─────────────────────────────────────────

/**
 * Extract plain text from content that may be in AG-UI protocol format.
 *
 * The backend may store user message content as:
 * - Plain text: "Show revenue by region"
 * - Python repr: "[TextInputContent(type='text', text='Show revenue by region')]"
 * - JSON array: '[{"type":"text","text":"Show revenue by region"}]'
 *
 * This function normalizes all formats to plain text.
 * NOTE: The backend should ideally store plain text — this is a defensive fallback.
 */
function extractTextContent(content: string): string {
  if (!content) return '';

  const trimmed = content.trim();

  // Plain text (most common / correct case) — doesn't start with [
  if (!trimmed.startsWith('[')) return trimmed;

  // JSON array: [{"type":"text","text":"..."}]
  try {
    const parsed = JSON.parse(trimmed);
    if (Array.isArray(parsed)) {
      return parsed
        .filter((p: any) => p.type === 'text' && p.text)
        .map((p: any) => p.text)
        .join('');
    }
  } catch {
    // Not JSON — try Python repr format
  }

  // Python repr: [TextInputContent(type='text', text='...')]
  const pyMatches = [...trimmed.matchAll(/text=['"](.*?)['"]\)/g)];
  if (pyMatches.length > 0) {
    return pyMatches.map((m) => m[1]).join('');
  }

  // Unrecognized format — return as-is
  return trimmed;
}

/**
 * Convert backend messages to ChatMessage[] for the chat panel.
 * Skips tool invocations and tool results (those are handled separately for canvas).
 */
export function mapBackendMessages(messages: BackendMessage[]): ChatMessage[] {
  const result: ChatMessage[] = [];

  for (const msg of messages) {
    // User messages → chat bubble
    if (msg.role === 'user') {
      result.push({
        id: randomUUID(),
        role: 'user',
        content: extractTextContent(msg.content),
        timestamp: new Date(),
        isStreaming: false,
        a2uiPayload: null,
        toolCalls: null,
      });
      continue;
    }

    // Assistant text responses (no tool_call_name) → chat bubble
    if (msg.role === 'assistant' && !msg.tool_call_name) {
      result.push({
        id: msg.message_id || randomUUID(),
        role: 'assistant',
        content: msg.content,
        timestamp: new Date(),
        isStreaming: false,
        a2uiPayload: null,
        toolCalls: null,
      });
      continue;
    }

    // Skip: assistant with tool_call_name (tool invocation indicator)
    // Skip: tool results (rendered on canvas via extractA2UIPayloads)
  }

  return result;
}

