    11→
    12→/**
    13→ * CanvasPanelComponent
    14→ *
    15→ * Main canvas panel for displaying visualizations as a scrollable feed.
    16→ * All visualizations persist — new ones are appended, not replaced.
    17→ */
    18→@Component({
    19→  selector: 'app-canvas-panel',
    20→  standalone: true,
    21→  changeDetection: ChangeDetectionStrategy.OnPush,
    22→  imports: [
    23→    CommonModule,
    24→    Surface,
    25→    CanvasEmptyStateComponent,
    26→    CanvasToolbarComponent,
    27→    LoadingSkeletonComponent,
    28→    AutoScrollDirective,
    29→  ],
    30→  template: `
    31→    <div class="h-full flex flex-col bg-gradient-to-br from-gray-50 to-white overflow-hidden">
    32→      @if (!hasVisualization() && !isLoading()) {
    33→        <!-- Empty State -->
    34→        <app-canvas-empty-state
    35→          [hasConversation]="hasConversation()"
    36→          (onExampleClick)="handleExampleClick($event)" />
    37→      } @else {
    38→        <!-- Toolbar -->
    39→        <app-canvas-toolbar [title]="toolbarTitle()" />
    40→
    41→        <!-- Visualization feed -->
    42→        <div class="flex-1 overflow-auto p-8" appAutoScroll>
    43→          <div class="space-y-8">
    44→            @for (entry of allSurfaces(); track entry.id) {
    45→              <div class="w-full animate-fadeIn">
    46→                <a2ui-surface
    47→                  [surfaceId]="entry.id"
    48→                  [surface]="entry.surface" />
    49→              </div>
    50→            }
    51→
    52→            @if (isLoading()) {
    53→              <div class="max-w-6xl mx-auto">
    54→                <app-loading-skeleton type="chart" [height]="'500px'" />
    55→              </div>
    56→            }
    57→
    58→            @if (catalogError()) {
    59→              <div class="max-w-2xl mx-auto p-4 bg-red-50 border border-red-200 rounded-lg">
    60→                <div class="flex items-start gap-3">
    61→                  <svg class="w-5 h-5 text-red-500 mt-0.5 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor">
    62→                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z" />
    63→                  </svg>
    64→                  <div>
    65→                    <p class="text-sm font-medium text-red-800">Visualization Error</p>
    66→                    <p class="text-sm text-red-700 mt-1">{{ catalogError() }}</p>
