     1→import { Injectable, inject, signal } from '@angular/core';
     2→import { firstValueFrom } from 'rxjs';
     3→import { ThreadService } from './thread.service';
     4→import { ChatStateService } from './chat-state.service';
     5→import { AgUiService } from './ag-ui.service';
     6→import { A2UIEventService } from './a2ui-event.service';
     7→import { SharedStateService } from './shared-state.service';
     8→import {
     9→  Thread,
    10→  mapBackendMessages,
    11→  extractA2UIPayloads,
    12→} from '../models/thread.models';
    13→
    14→const STORAGE_KEY = 'analytics-agent:active-thread';
    15→
    16→/**
    17→ * ConversationService
    18→ *
    19→ * Orchestrates thread management: listing, switching, creating, deleting.
    20→ * Coordinates ThreadService, ChatStateService, AgUiService, A2UIEventService,
    21→ * and SharedStateService to keep all state in sync during thread operations.
    22→ */
    23→@Injectable({
    24→  providedIn: 'root',
    25→})
    26→export class ConversationService {
    27→  private threadService = inject(ThreadService);
    28→  private chatState = inject(ChatStateService);
    29→  private agUiService = inject(AgUiService);
    30→  private a2uiEventService = inject(A2UIEventService);
    31→  private sharedState = inject(SharedStateService);
    32→
    33→  /** Currently active thread ID (null = new unsaved conversation) */
    34→  readonly activeThreadId = signal<string | null>(null);
    35→
    36→  /** Thread list for the sidebar */
    37→  readonly threads = signal<Thread[]>([]);
    38→
    39→  /** Loading state for history fetch */
    40→  readonly isLoadingHistory = signal<boolean>(false);
    41→
    42→  /** Initialize: restore last active thread from localStorage */
    43→  async init(): Promise<void> {
    44→    const savedId = this.restoreActiveThread();
    45→    await this.loadThreads();
    46→    if (savedId) {
    47→      await this.switchThread(savedId);
    48→    }
    49→  }
    50→
    51→  /** Fetch thread list from backend */
    52→  async loadThreads(): Promise<void> {
    53→    try {
    54→      const response = await firstValueFrom(this.threadService.getThreads());
    55→      this.threads.set(response.threads);
    56→    } catch (error) {
    57→      console.error('Failed to load threads:', error);
    58→    }
    59→  }
    60→
    61→  /** Switch to an existing thread: load messages, rebuild chat + canvas */
    62→  async switchThread(threadId: string): Promise<void> {
    63→    this.isLoadingHistory.set(true);
    64→    try {
    65→      // 1. Fetch messages from backend
    66→      const response = await firstValueFrom(
    67→        this.threadService.getMessages(threadId),
    68→      );
    69→
    70→      // 2. Clear current state
    71→      this.chatState.clearMessages();
    72→      this.a2uiEventService.clearSurface();
    73→      this.sharedState.resetContext();
    74→
    75→      // 3. Map backend messages → ChatMessage[] and load into chat
    76→      const chatMessages = mapBackendMessages(response.messages);
    77→      this.chatState.loadMessages(chatMessages);
    78→
    79→      // 4. Replay A2UI surfaces for canvas restoration (Phase 4)
    80→      const a2uiPayloads = extractA2UIPayloads(response.messages);
    81→      for (const payload of a2uiPayloads) {
    82→        this.a2uiEventService.handleA2UIMessages(
    83→          payload.surfaceId,
    84→          payload.messages,
    85→        );
    86→      }
    87→
    88→      // 5. Point HttpAgent at the selected thread
    89→      this.agUiService.switchThread(threadId);
    90→
    91→      // 6. Persist active thread
    92→      this.activeThreadId.set(threadId);
    93→      this.persistActiveThread(threadId);
    94→    } catch (error) {
    95→      console.error('Failed to switch thread:', error);
    96→      this.chatState.setError('Failed to load conversation history');
    97→    } finally {
    98→      this.isLoadingHistory.set(false);
    99→    }
   100→  }
   101→
   102→  /** Start a brand new conversation: clear everything, let HttpAgent auto-generate threadId */
   103→  startNewConversation(): void {
   104→    this.chatState.clearMessages();
   105→    this.a2uiEventService.clearSurface();
   106→    this.sharedState.resetContext();
   107→    this.agUiService.startNewThread();
   108→    this.activeThreadId.set(null);
   109→    this.clearPersistedThread();
   110→  }
   111→
   112→  /** Rename a thread title */
   113→  async renameThread(threadId: string, title: string): Promise<void> {
   114→    const trimmed = title.trim();
   115→    if (!trimmed) return;
   116→    try {
   117→      await firstValueFrom(this.threadService.updateThread(threadId, trimmed));
   118→      this.threads.update((list) =>
   119→        list.map((t) => (t.id === threadId ? { ...t, title: trimmed } : t)),
   120→      );
   121→    } catch (error) {
   122→      console.error('Failed to rename thread:', error);
   123→    }
   124→  }
   125→
   126→  /** Delete a thread from backend and local state */
   127→  async deleteThread(threadId: string): Promise<void> {
   128→    try {
   129→      await firstValueFrom(this.threadService.deleteThread(threadId));
   130→      // Remove from local list
   131→      this.threads.update((list) => list.filter((t) => t.id !== threadId));
   132→      // If we deleted the active thread, start fresh
   133→      if (this.activeThreadId() === threadId) {
   134→        this.startNewConversation();
   135→      }
   136→    } catch (error) {
   137→      console.error('Failed to delete thread:', error);
   138→    }
   139→  }
   140→
   141→  /**
   142→   * Called after a successful agent run to sync thread state.
   143→   * - Captures the auto-generated threadId for new conversations
   144→   * - Auto-titles new threads from the first user message
   145→   * - Refreshes the thread list so new threads appear in sidebar
   146→   */
   147→  async onRunCompleted(): Promise<void> {
   148→    const currentThreadId = this.agUiService.threadId;
   149→    const isNewThread = !this.activeThreadId() && !!currentThreadId;
   150→
   151→    if (isNewThread) {
   152→      this.activeThreadId.set(currentThreadId);
   153→      this.persistActiveThread(currentThreadId);
   154→    }
   155→
   156→    await this.loadThreads();
   157→
   158→    // Auto-title: if this was a new thread, generate a title from the first user message
   159→    if (isNewThread) {
   160→      const firstUserMsg = this.chatState
   161→        .messages()
   162→        .find((m) => m.role === 'user');
   163→      if (firstUserMsg?.content) {
   164→        const title = this.generateTitle(firstUserMsg.content);
   165→        try {
   166→          await firstValueFrom(
   167→            this.threadService.updateThread(currentThreadId, title),
   168→          );
   169→          // Update local thread list with new title
   170→          this.threads.update((list) =>
   171→            list.map((t) =>
   172→              t.id === currentThreadId ? { ...t, title } : t,
   173→            ),
   174→          );
   175→        } catch (error) {
   176→          console.error('Failed to auto-title thread:', error);
   177→        }
   178→      }
   179→    }
   180→  }
   181→
   182→  /**
   183→   * Generate a short title from a user message.
   184→   * Truncates to ~40 characters at a word boundary.
   185→   */
   186→  private generateTitle(message: string): string {
   187→    const cleaned = message.replace(/\s+/g, ' ').trim();
   188→    if (cleaned.length <= 40) return cleaned;
   189→
   190→    const truncated = cleaned.substring(0, 40);
   191→    const lastSpace = truncated.lastIndexOf(' ');
   192→    return (lastSpace > 20 ? truncated.substring(0, lastSpace) : truncated) + '...';
   193→  }
   194→
   195→  private persistActiveThread(threadId: string): void {
   196→    try {
   197→      localStorage.setItem(STORAGE_KEY, threadId);
   198→    } catch {
   199→      // localStorage unavailable — ignore
   200→    }
   201→  }
   202→
   203→  private restoreActiveThread(): string | null {
   204→    try {
   205→      return localStorage.getItem(STORAGE_KEY);
   206→    } catch {
   207→      return null;
   208→    }
   209→  }
   210→
   211→  private clearPersistedThread(): void {
   212→    try {
   213→      localStorage.removeItem(STORAGE_KEY);
   214→    } catch {
   215→      // ignore
   216→    }
   217→  }
   218→}
